isValidId(String).code:
{
    // e.g.
    // 17:36002278-36002277:1/A
    //  1:206811015-206811016:1/-
    return (!id.contains("N") && !id.contains("undefined") && !id.contains("g.") && id.contains("-") && // should have two :
    (id.length() - id.replace(":", "").length() == 2) && // should have one /
    (id.length() - id.replace("/", "").length() == 1) && // should be (digit|X|Y|MT):digit-digit:1/character(s)
