initPostEnrichmentService(String, List,.code:
{
    // The post enrichment service enriches the annotation after saving
    // the original annotation data to the repository. Any enrichment
    // performed by the post enrichment service is not saved
    // to the annotation repository.
    EnrichmentService postEnrichmentService = new VEPEnrichmentService();
    // always register an isoform override enricher
    // if the source is invalid we will use the default override source
    postEnrichmentService.registerEnricher(new IsoformAnnotationEnricher(isoformOverrideSource, isoformOverrideSource, ensemblService));
    if (fields != null && fields.contains("hotspots")) {
        postEnrichmentService.registerEnricher(new HotspotAnnotationEnricher("cancerHotspots", hotspotService, true));
    }
    if (fields != null && fields.contains("mutation_assessor")) {
        postEnrichmentService.registerEnricher(new MutationAssessorAnnotationEnricher("mutation_assessor", mutationAssessorService));
    }
    if (fields != null && fields.contains("nucleotide_context")) {
        postEnrichmentService.registerEnricher(new NucleotideContextAnnotationEnricher("nucleotide_context", nucleotideContextService));
    }
    if (fields != null && fields.contains("my_variant_info")) {
        postEnrichmentService.registerEnricher(new MyVariantInfoAnnotationEnricher("my_variant_info", myVariantInfoService));
    }
    if (fields != null && fields.contains("ptms")) {
        postEnrichmentService.registerEnricher(new PostTranslationalModificationEnricher("ptm", postTranslationalModificationService));
    }
    if (fields != null && fields.contains("signal")) {
        postEnrichmentService.registerEnricher(new SignalAnnotationEnricher("signal", signalMutationService));
    }
    if (fields != null && fields.contains("oncokb")) {
        String oncokbToken = null;
        if (token != null && token.containsKey("oncokb")) {
            oncokbToken = token.get("oncokb");
        }
        postEnrichmentService.registerEnricher(new OncokbAnnotationEnricher("oncokb", oncokbService, variantAnnotationSummaryService, oncokbToken));
    }
    if (fields != null && fields.contains("clinvar")) {
        postEnrichmentService.registerEnricher(new ClinvarVariantAnnotationEnricher("clinvar", clinvarVariantAnnotationService));
    }
    if (fields != null && fields.contains("annotation_summary")) {
        postEnrichmentService.registerEnricher(new CanonicalTranscriptAnnotationEnricher("annotation_summary", variantAnnotationSummaryService));
    }
    return postEnrichmentService;
}

