            // the second format will throw an IndexOutOfBoundsException when trying to access substring index 1
            if (transcriptConsequence.getHgvsc() != null && transcriptConsequence.getHgvsc().contains("dup")) {
                if (aaParts[1].length() == 1) {
                    hgvspShort = "p." + aaParts[1].substring(0, 1) + String.valueOf(transcriptConsequence.getProteinStart() - 1) + "dup";
                } else {
                    // e.g for KIT p.Q575_G592dup
                    // 4:g.55593656_55593657insCAACTTCCTTATGATCACAAATGGGAGTTTCCCAGAAACAGGCTGAGTTTTGGT
                    hgvspShort = "p." + aaParts[1].substring(0, 1) + String.valueOf(transcriptConsequence.getProteinStart() + 1) + "_" + aaParts[1].substring(aaParts[1].length() - 1) + // protein end for an instertion will be protein start + 1, so use length of amino acid insted
                    String.valueOf(transcriptConsequence.getProteinStart() + aaParts[1].length()) + "dup";
                }
            } else {
                hgvspShort = "p.X" + transcriptConsequence.getProteinStart() + "_X" + transcriptConsequence.getProteinEnd() + "ins" + aaParts[1];
            }
        } else if (transcriptConsequence.getConsequenceTerms() != null && transcriptConsequence.getConsequenceTerms().get(0).toLowerCase().contains("inframe_deletion")) {
            hgvspShort = "p." + aaParts[0] + "del";
        } else {
            hgvspShort = "p." + aaParts[0] + transcriptConsequence.getProteinStart();
            if (transcriptConsequence.getConsequenceTerms() != null && transcriptConsequence.getConsequenceTerms().get(0).toLowerCase().contains("frameshift_variant")) {
                hgvspShort += "fs";
            } else {
                hgvspShort += aaParts[1];
            }
        }
    } catch (Exception e) {
        // LOG.debug("Failed to salvage HGVSp_Short from protein start, amino acids, and consequence terms");
    }
    return hgvspShort;
}

