{
    String defaultValue = "Targeted_Region";
    if (variant == null || (variantType == null && !variant.contains("splice"))) {
        return defaultValue;
    } else {
        variant = variant.toLowerCase();
    }
    if ((variant.equals("frameshift_variant") || variant.equals("protein_altering_variant") || variant.equals("coding_sequence_variant")) && !isInframe) {
        if (variantType.equals("DEL")) {
            return "Frame_Shift_Del";
        } else if (variantType.equals("INS")) {
            return "Frame_Shift_Ins";
        }
    } else if ((variant.equals("protein_altering_variant") || variant.equals("coding_sequence_variant")) && isInframe) {
        if (variantType.equals("DEL")) {
            return "In_Frame_Del";
        } else if (variantType.equals("INS")) {
            return "In_Frame_Ins";
        }
    }
    return VARIANT_MAP.getOrDefault(variant, defaultValue);
}

