getSplitAminoAcids(String).code:
{
    if (aminoAcids != null) {
        if (aminoAcids.contains("/")) {
            return aminoAcids.split("/");
        } else {
            // is silent mutation e.g. E -> E
            String[] splitAAs = { aminoAcids, aminoAcids };
            return splitAAs;
        }
    } else {
        return null;
    }
}

