{
    Map<String, VariantAnnotation> variantMockData = this.variantAnnotationMockData.generateData();
    assertNull("Null annotation input -> Null output", this.strandSignResolver.resolve(null));
    assertNull("Variant annotation with null strand -> Null output", this.strandSignResolver.resolve(new VariantAnnotation()));
    VariantAnnotation annotation = new VariantAnnotation();
    annotation.setStrand(-1);
    assertEquals("Variant annotation with strand < 0 -> Minus (-)", "-", this.strandSignResolver.resolve(annotation));
    annotation = new VariantAnnotation();
    annotation.setStrand(0);
    assertEquals("Variant annotation with strand >= 0 -> Plus (+)", "+", this.strandSignResolver.resolve(annotation));
